<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\{Artisan,File}; use ZipArchive;
class BackupController extends Controller {
 public function index(){return view('configuration.backups.index');}
 public function download(){ $name='wesarafi-backup-'.now()->format('Y-m-d_H-i-s');$dir=storage_path('app/backups/'.$name);File::ensureDirectoryExists($dir);$db=config('database.default');if($db==='sqlite'){File::copy(database_path('database.sqlite'),$dir.'/database.sqlite');}else{$file=$dir.'/database.sql';$cmd=sprintf('mysqldump --single-transaction --routines --triggers -h%s -P%s -u%s -p%s %s > %s',escapeshellarg(config('database.connections.mysql.host')),escapeshellarg(config('database.connections.mysql.port')),escapeshellarg(config('database.connections.mysql.username')),escapeshellarg(config('database.connections.mysql.password')),escapeshellarg(config('database.connections.mysql.database')),escapeshellarg($file));exec($cmd,$out,$code);abort_if($code!==0,500,'Database backup failed.');} $zipPath=storage_path('app/backups/'.$name.'.zip');$zip=new ZipArchive;$zip->open($zipPath,ZipArchive::CREATE);foreach(File::allFiles($dir) as $f)$zip->addFile($f->getPathname(),$f->getFilename());$zip->close();File::deleteDirectory($dir);return response()->download($zipPath)->deleteFileAfterSend(true);}
 public function restore(Request $r){
  // Temporarily disabled until archive extraction and database import are hardened.
  abort(503, 'Database restore is temporarily disabled for security maintenance.');
$r->validate(['backup'=>'required|file|mimes:zip|max:204800','confirmation'=>'required|in:RESTORE']);$tmp=storage_path('app/restore-'.uniqid());File::ensureDirectoryExists($tmp);$zip=new ZipArchive;abort_unless($zip->open($r->file('backup')->getRealPath())===true,422,'Invalid backup archive.');$zip->extractTo($tmp);$zip->close();if(File::exists($tmp.'/database.sqlite')&&config('database.default')==='sqlite')File::copy($tmp.'/database.sqlite',database_path('database.sqlite'));elseif(File::exists($tmp.'/database.sql')&&config('database.default')==='mysql'){$cmd=sprintf('mysql -h%s -P%s -u%s -p%s %s < %s',escapeshellarg(config('database.connections.mysql.host')),escapeshellarg(config('database.connections.mysql.port')),escapeshellarg(config('database.connections.mysql.username')),escapeshellarg(config('database.connections.mysql.password')),escapeshellarg(config('database.connections.mysql.database')),escapeshellarg($tmp.'/database.sql'));exec($cmd,$o,$code);abort_if($code!==0,500,'Database restore failed.');}else abort(422,'Backup does not match the active database driver.');File::deleteDirectory($tmp);Artisan::call('optimize:clear');return back()->with('success','Backup restored successfully.');}
}
